def proverb(*parts, qualifier=None):
    if not parts:
        return []

    lines = [
        f"For want of a {a} the {b} was lost."
        for a, b in zip(parts, parts[1:])
    ]

    first = f"a {qualifier} " if qualifier else "a "
    lines.append(f"And all for the want of {first}{parts[0]}.")

    return lines

